    count = count_video(video_path)
    rows.append({'filename': video_path.name, 'number': count})

# Write Excel with only one sheet named "results"
output_path = video_dir / 'count.xlsx'
with pd.ExcelWriter(output_path, engine='openpyxl') as writer:
    pd.DataFrame(rows, columns=['filename', 'number']).to_excel(
        writer, sheet_name='results', index=False
    )

print('Wrote', output_path, 'rows', rows)
